import React, { useEffect, useState } from 'react';
import './App.css';

export interface TeamMember {
  id: number;
  name: string;
  role: string;
}

export type SourceMode = 'ok' | 'empty' | 'flaky';

type LoadedTeam = {
  status: 'success';
  source: SourceMode;
  members: TeamMember[];
  refreshing: boolean;
  refreshError: string | null;
};

type RequestState =
  | { status: 'loading' }
  | { status: 'empty' }
  | { status: 'error'; message: string }
  | LoadedTeam;

const TEAM: TeamMember[] = [
  { id: 1, name: 'Alice Johnson', role: 'Frontend engineer' },
  { id: 2, name: 'Bob Smith', role: 'Product designer' },
  { id: 3, name: 'Charlie Kim', role: 'Backend engineer' },
  { id: 4, name: 'Diana Lopez', role: 'Engineering manager' },
  { id: 5, name: 'Ethan Brown', role: 'QA engineer' },
  { id: 6, name: 'Fiona Patel', role: 'Data analyst' }
];

let flakyRequests = 0;

// Fake API: responds after 400ms.
// - 'ok' resolves with the whole team
// - 'empty' resolves with an empty list
// - 'flaky' rejects every odd request, so the first request fails and a retry succeeds
// Aborting the signal stops the timer and rejects with an AbortError.
export function fetchTeam(mode: SourceMode, signal?: AbortSignal): Promise<TeamMember[]> {
  return new Promise((resolve, reject) => {
    const timerId = window.setTimeout(() => {
      if (mode === 'empty') {
        resolve([]);
        return;
      }

      if (mode === 'flaky') {
        flakyRequests += 1;
        if (flakyRequests % 2 === 1) {
          reject(new Error('Network timeout'));
          return;
        }
      }

      resolve(TEAM.map((member) => ({ ...member })));
    }, 400);

    signal?.addEventListener(
      'abort',
      () => {
        window.clearTimeout(timerId);
        reject(new DOMException('Request cancelled', 'AbortError'));
      },
      { once: true }
    );
  });
}

function isAbortError(error: unknown): boolean {
  return error instanceof DOMException && error.name === 'AbortError';
}

function toErrorMessage(error: unknown): string {
  return error instanceof Error && error.message ? error.message : 'Unknown error';
}

// Rows are worth keeping only while they still belong to the selected source.
function showsRowsFrom(state: RequestState, source: SourceMode): state is LoadedTeam {
  return state.status === 'success' && state.source === source;
}

export default function App() {
  const [mode, setMode] = useState<SourceMode>('ok');
  const [attempt, setAttempt] = useState(0);
  const [request, setRequest] = useState<RequestState>({ status: 'loading' });

  useEffect(() => {
    const controller = new AbortController();

    setRequest((current) =>
      showsRowsFrom(current, mode)
        ? { ...current, refreshing: true, refreshError: null }
        : { status: 'loading' }
    );

    fetchTeam(mode, controller.signal)
      .then((members) => {
        setRequest(
          members.length
            ? { status: 'success', source: mode, members, refreshing: false, refreshError: null }
            : { status: 'empty' }
        );
      })
      .catch((error: unknown) => {
        if (isAbortError(error)) return;
        const message = toErrorMessage(error);
        setRequest((current) =>
          showsRowsFrom(current, mode)
            ? { ...current, refreshing: false, refreshError: message }
            : { status: 'error', message }
        );
      });

    return () => controller.abort();
  }, [mode, attempt]);

  function handleModeChange(event: React.ChangeEvent<HTMLSelectElement>) {
    setMode(event.target.value as SourceMode);
  }

  function requestAgain() {
    setAttempt((current) => current + 1);
  }

  const loaded = request.status === 'success' ? request : null;

  return (
    <main className="main">
      <section className="card">
        <header className="header">
          <h1 className="title">Team Directory</h1>
          <p className="subtitle">A refresh keeps the list on screen. A new source starts clean.</p>
        </header>

        <div className="field">
          <label className="label" htmlFor="mode-select">Data source</label>
          <select id="mode-select" className="mode" value={mode} onChange={handleModeChange}>
            <option value="ok">Team (6 members)</option>
            <option value="empty">Empty team</option>
            <option value="flaky">Flaky network</option>
          </select>
        </div>

        <div className="status-row" aria-live="polite">
          {request.status === 'loading' && <span className="status status--loading">Loading team…</span>}
          {request.status === 'empty' && <span className="status status--muted">0 members</span>}
          {request.status === 'error' && (
            <span className="status status--error" role="alert">
              Could not load the team: {request.message}
            </span>
          )}
          {loaded?.refreshing && <span className="status status--loading">Refreshing team…</span>}
          {loaded?.refreshError && (
            <span className="status status--error" role="alert">
              Could not refresh the team: {loaded.refreshError}
            </span>
          )}
          {loaded && !loaded.refreshing && !loaded.refreshError && (
            <span className="status status--muted">{loaded.members.length} members</span>
          )}
        </div>

        {(request.status === 'error' || loaded?.refreshError) && (
          <button type="button" className="retry" onClick={requestAgain}>
            Retry
          </button>
        )}

        {loaded && (
          <button type="button" className="refresh" disabled={loaded.refreshing} onClick={requestAgain}>
            Refresh
          </button>
        )}

        {loaded && (
          <ul className="results" aria-busy={loaded.refreshing}>
            {loaded.members.map((member) => (
              <li key={member.id} className="user-row">
                <div className="user-name">{member.name}</div>
                <div className="user-role">{member.role}</div>
              </li>
            ))}
          </ul>
        )}

        {request.status === 'empty' && <p className="empty">No team members yet.</p>}
      </section>
    </main>
  );
}

